import java.util.*;record Item(String name,int quantity){}class Inventory{private final Map<String,Item> items=new TreeMap<>();void add(String id,String name,int quantity){items.put(id,new Item(name,quantity));}void sell(String id,int quantity){Item item=items.get(id);if(item!=null&&item.quantity()>=quantity)items.put(id,new Item(item.name(),item.quantity()-quantity));}void print(){items.forEach((id,item)->System.out.println(id+" "+item.name()+" "+item.quantity()));}}class Main{public static void main(String[] args){Inventory inventory=new Inventory();inventory.add("P1","Keyboard",10);inventory.add("P2","Mouse",15);inventory.sell("P1",3);inventory.print();}}
